import { setTimeout as sleep } from 'node:timers/promises';

async function fetchBook(id) {
  await sleep(300); // stands in for a database or network call
  return { id, title: `Book ${id}` };
}

console.time('one after another');
const a = await fetchBook(1);
const b = await fetchBook(2);
console.timeEnd('one after another');

console.time('at the same time');
const [c, d] = await Promise.all([fetchBook(1), fetchBook(2)]);
console.timeEnd('at the same time');

console.log(a.title, b.title, c.title, d.title);

import { readFile } from 'node:fs/promises';

async function loadConfig() {
  try {
    return JSON.parse(await readFile('config.json', 'utf8'));
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
    console.error('No config.json, using defaults');
    return { port: 3000 };
  }
}

console.log(await loadConfig());

